CREATE POLICY "Housekeepers upload their photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='housekeeper-portfolios' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'cleaner'));
CREATE POLICY "Housekeepers manage own photos" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='housekeeper-portfolios' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'cleaner'));
CREATE POLICY "Housekeepers delete own photos" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='housekeeper-portfolios' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'cleaner'));
CREATE POLICY "Published housekeeper photos" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='housekeeper-portfolios' AND EXISTS(SELECT 1 FROM public.housekeeper_portfolios p WHERE p.published AND public.has_role(p.user_id,'cleaner') AND (p.portrait_path=name OR EXISTS(SELECT 1 FROM public.housekeeper_gallery g WHERE g.user_id=p.user_id AND (g.before_path=name OR g.after_path=name)))));